/*
 ******************************************************************************
 * TAREA #1 Valentina Lopera Urrego - GPIO, TIMERS Y EXTI (Taller V, 2026-S2)
 *
 * DESCRIPCIÓN DEL SISTEMA
 * Contador de 16 bits (0 a 65535) que se muestra en un display de 7 segmentos
 * de 4 dígitos. Dos fotointerruptores de ranura lo incrementan y lo decrementan
 * en 1 por cada interrupción. Al pasar de 65535 vuelve a 0 y al bajar de 0 pasa
 * a 65535. Programación bare-metal con CMSIS.
 *
 * HARDWARE UTILIZADO
 * - Tarjeta Nucleo STM32F411RE, reloj interno HSI de 16 MHz.
 * - Botón de reset de la placa: reinicia el MCU en cualquier momento.
 * - LED de estado externo en PH1: titila cada BLINK_PERIOD_MS (250 ms, es decir
 *   2 Hz) para evidenciar que el MCU y el programa están funcionando.
 * - Display KEM-5641-BSR de 4 dígitos, ánodo común.
 *   Cada dígito se enciende con un transistor PNP cuya base se pone en bajo.
 *   Segmentos: a=PB12, b=PA12, c=PC11, d=PC10, e=PC12, f=PA11, g=PD2.
 *   Dígitos (bases de los PNP): 1=PC5, 2=PC6, 3=PC2, 4=PB7.
 * - Fotointerruptor 1 en PC3 (EXTI3, flanco de BAJADA): incrementa el contador.
 * - Fotointerruptor 2 en PA0 (EXTI0, flanco de SUBIDA): decrementa el contador.
 *   Ambos con pull-up externo de 10 kOhm.
 *
 * FUNCIONAMIENTO
 * Las interrupciones solo piden una tarea a la máquina de estados (variable
 * fsm_Next_state) y el main la ejecuta con action_fsm. Si no hay nada pendiente
 * el estado es IDLE y el main no hace nada.
 * - SysTick (1 ms): lleva el tiempo (ticks), se usa para el antirrebote de
 *   50 ms de los sensores y pide el parpadeo del LED de estado (BLINK_LED).
 * - TIM2 (2 ms): timer independiente que gobierna el refresco del display y
 *   pide REFRESH_DISPLAY. En cada turno se apagan los 4 dígitos (evita el
 *   fantasma), se dibujan los segmentos del dígito siguiente y se enciende
 *   solo ese dígito. Con 4 dígitos cada uno se refresca cada 8 ms (125 Hz) y el
 *   ojo los ve todos encendidos.
 * - EXTI3 y EXTI0: piden COUNT_UP y COUNT_DOWN, y action_fsm actualiza el
 *   contador y separa sus dígitos.
 * Interrupciones usadas: SysTick, TIM2, EXTI0 y EXTI3.
 ******************************************************************************
 */

#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"


// Definiendo constantes de configuración
#define SYSTICK_RELOAD     (16000U - 1U) // Recarga para 1 ms con frecuencia de 16 MHz
#define REFRESH_PERIOD_MS  2U            // Periodo de refresco del display en ms
#define TIM2_PRESCALER     (16000U - 1U) // Divisor por 16000, para que el reloj del TIM2 sea de 1 kHz
#define TIM2_RELOAD        (REFRESH_PERIOD_MS - 1U) // Recarga del TIM2 para el periodo de refresco
#define DEBOUNCE_MS        50U           // Tiempo de antirrebote de los sensores en ms
#define BLINK_PERIOD_MS    250U         // Periodo del parpadeo del LED de estado en ms

typedef enum {
    IDLE = 0,        // Sin tareas pendientes
    COUNT_UP,        // Incrementar el contador
    COUNT_DOWN,      // Decrementar el contador
    REFRESH_DISPLAY, // Refrescar un dígito del display
    BLINK_LED        // Cambiar el LED de estado
} homework_states_t;

typedef enum {
    DISPLAY_1 = 0,   // Dígito 1 (miles)
    DISPLAY_2,       // Dígito 2 (centenas)
    DISPLAY_3,       // Dígito 3 (decenas)
    DISPLAY_4        // Dígito 4 (unidades)
} display_to_show_t;

typedef struct {
    GPIO_TypeDef *port; // Puerto del pin
    uint8_t pin;        // Número del pin dentro del puerto
} pin_map_t;

const pin_map_t segment_pins[7] = {  // Pines de los segmentos (activos en bajo)
    {GPIOB, 12}, // Segmento a, pin 11 del display
    {GPIOA, 12}, // Segmento b, pin 7 del display
    {GPIOC, 11}, // Segmento c, pin 4 del display
    {GPIOC, 10}, // Segmento d, pin 2 del display
    {GPIOC, 12}, // Segmento e, pin 1 del display
    {GPIOA, 11}, // Segmento f, pin 10 del display
    {GPIOD, 2}   // Segmento g, pin 5 del display
};

const pin_map_t digit_pins[4] = {    // Pines de las bases de los PNP (activos en bajo)
    {GPIOC, 5},  // Dígito 1 (miles), pin 12 del display
    {GPIOC, 6},  // Dígito 2 (centenas), pin 9 del display
    {GPIOC, 2},  // Dígito 3 (decenas), pin 8 del display
    {GPIOB, 7}   // Dígito 4 (unidades), pin 6 del display
};

volatile homework_states_t fsm_Next_state = IDLE; // Próximo estado de la FSM (lo modifican las interrupciones)
volatile uint32_t ticks = 0;                      // Contador de milisegundos del SysTick
volatile uint32_t last_pa0_tick = 0;              // Último instante válido del sensor en PA0 (baja)
volatile uint32_t last_pc3_tick = 0;              // Último instante válido del sensor en PC3 (sube)
uint16_t counter = 0;                             // Valor actual del contador
uint8_t digits[4] = {0, 0, 0, 0};                 // Dígitos separados: miles, centenas, decenas, unidades
uint8_t display_index = 0;                        // Dígito que se refresca en cada turno

const uint8_t segment_table[10] = {               // Tabla de segmentos (1 = encendido, bit0=a ... bit6=g)
    0b00111111, // 0 , enciende el segmento a, b, c, d, e y f
    0b00000110, // 1 , enciende el segmento b y c
    0b01011011, // 2 , enciende el segmento a, b, d, e y g
    0b01001111, // 3 , enciende el segmento a, b, c, d y g
    0b01100110, // 4 , enciende el segmento b, c, f y g
    0b01101101, // 5 , enciende el segmento a, c, d, f y g
    0b01111101, // 6 , enciende el segmento a, c, d, e, f y g
    0b00000111, // 7 , enciende el segmento a, b y c
    0b01111111, // 8 , enciende el segmento a, b, c, d, e, f y g
    0b01101111  // 9 , enciende el segmento a, b, c, d, f y g
};

void init_gpio(void);
void init_timers(void);
void init_exti(void);
void action_fsm(homework_states_t state);
void update_display(display_to_show_t display);
void draw_number(uint8_t number);
void split_number(uint16_t);
uint32_t getTicks(void);

int main(void)
{
    // Configuración
    init_gpio(); // Configura los pines
    init_timers(); // Configura el SysTick y el TIM2
    init_exti(); // Configura las interrupciones externas

    // Ciclo principal
    while (1){

        if(fsm_Next_state != IDLE){ // Si hay algo pendiente
            action_fsm(fsm_Next_state); // Ejecuta la acción del estado
        }
    }

    return 0;
}

