void init_timers(void)
{
    // Configurando el SysTick a 1 ms
    SysTick->CTRL &= ~(SysTick_CTRL_ENABLE_Msk); // Deteniendo el contador antes de configurar
    SysTick->LOAD &= ~(SysTick_LOAD_RELOAD_Msk); // Limpiando el valor de recarga
    SysTick->LOAD |= (SYSTICK_RELOAD << SysTick_LOAD_RELOAD_Pos); // Recarga para 1 ms (16000 ciclos)
    SysTick->VAL = 0; // Reinicia el contador actual
    SysTick->CTRL &= ~(SysTick_CTRL_CLKSOURCE_Msk); // Limpiando la fuente de reloj
    SysTick->CTRL |= (0b1 << SysTick_CTRL_CLKSOURCE_Pos); // Seleccionando reloj del procesador (16 MHz)
    SysTick->CTRL &= ~(SysTick_CTRL_TICKINT_Msk); // Limpiando la interrupción del SysTick
    SysTick->CTRL |= (0b1 << SysTick_CTRL_TICKINT_Pos); // Habilitando la interrupción del SysTick
    SysTick->CTRL &= ~(SysTick_CTRL_ENABLE_Msk); // Limpiando el bit de encendido
    SysTick->CTRL |= (0b1 << SysTick_CTRL_ENABLE_Pos); // Habilitando el contador del SysTick

    // Prioridad del SysTick
    NVIC_SetPriority(SysTick_IRQn, 0); // Prioridad más alta que las EXTI para no perder eventos

    // Habilitando el reloj del TIM2
    RCC->APB1ENR &= ~(RCC_APB1ENR_TIM2EN_Msk); // Limpiando el bit de reloj
    RCC->APB1ENR |= (0b1 << RCC_APB1ENR_TIM2EN_Pos); // Activando el reloj del TIM2
    (void)RCC->APB1ENR; // Lectura de espera para estabilizar el reloj

    // Configurando el TIM2 para refrescar el display cada 2 ms
    TIM2->CR1 &= ~(TIM_CR1_CEN_Msk); // Deteniendo el contador antes de configurar
    TIM2->PSC &= ~(TIM_PSC_PSC_Msk); // Limpiando el divisor
    TIM2->PSC |= (TIM2_PRESCALER << TIM_PSC_PSC_Pos); // Divisor por 16000 (reloj del timer de 1 kHz)
    TIM2->ARR &= ~(TIM_ARR_ARR_Msk); // Limpiando el valor de recarga
    TIM2->ARR |= (TIM2_RELOAD << TIM_ARR_ARR_Pos); // Recarga para 2 ms
    TIM2->EGR &= ~(TIM_EGR_UG_Msk); // Limpiando el bit de actualización
    TIM2->EGR |= (0b1 << TIM_EGR_UG_Pos); // Forzando un update event para cargar el divisor y la recarga
    TIM2->SR &= ~(TIM_SR_UIF_Msk); // Limpiando la bandera de interrupción del update event

    // Habilitando la interrupción del TIM2
    TIM2->DIER &= ~(TIM_DIER_UIE_Msk); // Limpiando la habilitación de interrupción por update event
    TIM2->DIER |= (0b1 << TIM_DIER_UIE_Pos); // Habilitando la interrupción por update event
    NVIC_SetPriority(TIM2_IRQn, 1); // Prioridad del TIM2
    NVIC_EnableIRQ(TIM2_IRQn); // Habilitando el TIM2 en el NVIC

    // Encendiendo el TIM2
    TIM2->CR1 &= ~(TIM_CR1_CEN_Msk); // Limpiando el bit de encendido
    TIM2->CR1 |= (0b1 << TIM_CR1_CEN_Pos); // Habilitando el contador del TIM2
}

void init_exti(void)
{
    // Habilitando el reloj del SYSCFG
    RCC->APB2ENR &= ~(RCC_APB2ENR_SYSCFGEN_Msk); // Limpiando el bit de reloj
    RCC->APB2ENR |= (0b1 << RCC_APB2ENR_SYSCFGEN_Pos); // Activando el reloj del SYSCFG
    (void)RCC->APB2ENR; // Lectura de espera para estabilizar el reloj

    // Conectando PA0 a EXTI0 y PC3 a EXTI3
    SYSCFG->EXTICR[0] &= ~(SYSCFG_EXTICR1_EXTI0_Msk | SYSCFG_EXTICR1_EXTI3_Msk); // Limpiando la selección de puerto
    SYSCFG->EXTICR[0] |= ((0b0000 << SYSCFG_EXTICR1_EXTI0_Pos) | (0b0010 << SYSCFG_EXTICR1_EXTI3_Pos)); // Puerto A para EXTI0 y puerto C para EXTI3

    // Configurando los flancos (EXTI0 subida, EXTI3 bajada)
    EXTI->RTSR &= ~(EXTI_RTSR_TR0_Msk | EXTI_RTSR_TR3_Msk); // Limpiando el flanco de subida
    EXTI->RTSR |= ((0b1 << EXTI_RTSR_TR0_Pos) | (0b0 << EXTI_RTSR_TR3_Pos)); // Flanco de subida solo en EXTI0 (PA0, sensor 2)
    EXTI->FTSR &= ~(EXTI_FTSR_TR0_Msk | EXTI_FTSR_TR3_Msk); // Limpiando el flanco de bajada
    EXTI->FTSR |= ((0b0 << EXTI_FTSR_TR0_Pos) | (0b1 << EXTI_FTSR_TR3_Pos)); // Flanco de bajada solo en EXTI3 (PC3, sensor 1)

    // Limpiando banderas pendientes y desenmascarando las líneas
    EXTI->PR = ((0b1 << EXTI_PR_PR0_Pos) | (0b1 << EXTI_PR_PR3_Pos)); // Limpiando banderas (se escribe con =)
    EXTI->IMR &= ~(EXTI_IMR_MR0_Msk | EXTI_IMR_MR3_Msk); // Limpiando la máscara
    EXTI->IMR |= ((0b1 << EXTI_IMR_MR0_Pos) | (0b1 << EXTI_IMR_MR3_Pos)); // Habilitando las interrupciones EXTI0 y EXTI3

    // Configurando el NVIC
    NVIC_SetPriority(EXTI0_IRQn, 1); // Prioridad de EXTI0
    NVIC_SetPriority(EXTI3_IRQn, 1); // Prioridad de EXTI3
    NVIC_EnableIRQ(EXTI0_IRQn); // Habilitando EXTI0 en el NVIC
    NVIC_EnableIRQ(EXTI3_IRQn); // Habilitando EXTI3 en el NVIC
}

void action_fsm(homework_states_t state)
{
    // Consumiendo el estado pendiente
    __disable_irq(); // Evita que una interrupción cambie el estado a medias
    if(fsm_Next_state == state){ // Si no cambió mientras tanto
        fsm_Next_state = IDLE; // Libera la FSM para nuevos eventos
    }
    __enable_irq(); // Reactivando interrupciones

    // Ejecutando la acción del estado
    switch(state){
        case COUNT_UP:
            counter++; // Incrementa el contador (al pasar 65535 vuelve a 0)
            split_number(counter); // Actualiza los dígitos
            break;

        case COUNT_DOWN:
            counter--; // Decrementa el contador (desde 0 pasa a 65535)
            split_number(counter); // Actualiza los dígitos
            break;

        case REFRESH_DISPLAY:
            update_display((display_to_show_t)display_index); // Muestra el dígito del turno
            display_index = (display_index + 1U) & 0b11U; // Pasa al siguiente dígito (0 a 3)
            break;

        case BLINK_LED:
            GPIOH->ODR ^= (0b1 << GPIO_ODR_OD1_Pos); // Cambia el LED de estado (titila cada BLINK_PERIOD_MS)
            break;

        default:
            break; // Estado desconocido: no hace nada
    }
}

void update_display(display_to_show_t display)
{
    // Apagando los 4 dígitos para evitar fantasmas
    for(uint8_t i = 0; i < 4; i++){ // Recorre los 4 dígitos
        digit_pins[i].port->BSRR = (0b1U << digit_pins[i].pin); // Pin en alto (PNP apagado)
    }

    // Dibujando el número del dígito seleccionado
    draw_number(digits[display]); // Pone los segmentos del número

    // Encendiendo solo el dígito seleccionado
    digit_pins[display].port->BSRR = (0b1U << (digit_pins[display].pin + GPIO_BSRR_BR0_Pos)); // Pin en bajo (PNP encendido)
}

void draw_number(uint8_t number)
{
    uint8_t seg = 0; // Patrón de segmentos (1 = encendido)

    // Buscando el patrón del número
    if(number <= 9){ // Si es un dígito válido
        seg = segment_table[number]; // Toma el patrón de la tabla
    }                                // Si no, queda apagado

    // Escribiendo los segmentos (activos en bajo), cada uno en su puerto
    for(uint8_t i = 0; i < 7; i++){ // Recorre los segmentos a..g
        if(seg & (0b1 << i)){ // Si el segmento debe encenderse
            segment_pins[i].port->BSRR = (0b1U << (segment_pins[i].pin + GPIO_BSRR_BR0_Pos)); // Pin en bajo (encendido)
        } else { // Si debe apagarse
            segment_pins[i].port->BSRR = (0b1U << segment_pins[i].pin); // Pin en alto (apagado)
        }
    }
}

void split_number(uint16_t number)
{
    // Separando el número en dígitos
    digits[0] = (uint8_t)((number / 1000U) % 10U); // Miles (solo los 4 últimos dígitos, el 6 de 65535 no se muestra)
    digits[1] = (uint8_t)((number / 100U) % 10U);  // Centenas
    digits[2] = (uint8_t)((number / 10U) % 10U);   // Decenas
    digits[3] = (uint8_t)(number % 10U);           // Unidades
}

uint32_t getTicks(void)
{
    return ticks; // Devuelve los ms transcurridos desde el arranque
}

void SysTick_Handler(void)
{
    // Incrementando el tiempo
    ticks++; // Un ms más

    // Programando el parpadeo del LED de estado
    if((ticks % BLINK_PERIOD_MS) == 0U){ // Si pasó el periodo de parpadeo
        if(fsm_Next_state == IDLE){ // Solo si no hay otro evento pendiente
            fsm_Next_state = BLINK_LED; // Pide el cambio del LED a la FSM
        }
    }
}

void TIM2_IRQHandler(void)
{
    if(TIM2->SR & (0b1 << TIM_SR_UIF_Pos)){ // Verificamos si la interrupción fue por un update event
        TIM2->SR &= ~(0b1 << TIM_SR_UIF_Pos); // Limpiamos la bandera de interrupción

        // Programando el refresco del display cada 2 ms
        if(fsm_Next_state == IDLE){ // Solo si no hay otro evento pendiente
            fsm_Next_state = REFRESH_DISPLAY; // Pide el refresco a la FSM
        }
    }
}

void EXTI0_IRQHandler(void)
{
    if(EXTI->PR & (0b1 << EXTI_PR_PR0_Pos)){ // Si la bandera de EXTI0 está activa (PA0, sensor 2)
        EXTI->PR = (0b1 << EXTI_PR_PR0_Pos); // Limpiando la bandera (se escribe con =)

        uint32_t now = getTicks(); // Instante actual
        if((now - last_pa0_tick) >= DEBOUNCE_MS){ // Antirrebote de 50 ms
            last_pa0_tick = now; // Guarda el instante válido
            fsm_Next_state = COUNT_DOWN; // Pide decrementar el contador
        }
    }
}

void EXTI3_IRQHandler(void)
{
    if(EXTI->PR & (0b1 << EXTI_PR_PR3_Pos)){ // Si la bandera de EXTI3 está activa (PC3, sensor 1)
        EXTI->PR = (0b1 << EXTI_PR_PR3_Pos); // Limpiando la bandera (se escribe con =)

        uint32_t now = getTicks(); // Instante actual
        if((now - last_pc3_tick) >= DEBOUNCE_MS){ // Antirrebote de 50 ms
            last_pc3_tick = now; // Guarda el instante válido
            fsm_Next_state = COUNT_UP; // Pide incrementar el contador
        }
    }
}